import datetime

class InventoryManager:
    def __init__(self):
        self.stock_levels = {}
        self.supplier_records = {}
        self.purchase_orders = []
        self.alerts = []

    def check_stock(self, item_id, quantity):
        if item_id in self.stock_levels:
            current_quantity = self.stock_levels[item_id]
            if current_quantity >= quantity:
                return True
            else:
                reorder_point = self.calculate_reorder_point(item_id)
                if current_quantity < reorder_point:
                    self.generate_purchase_order(item_id, reorder_point - current_quantity)
                    return False
        return False

    def calculate_reorder_point(self, item_id):
        # Example calculation: 10% of daily sales
        daily_sales = 1000  # Replace with actual daily sales data
        reorder_point = daily_sales * 0.10
        return reorder_point

    def generate_purchase_order(self, item_id, quantity):
        order_date = datetime.datetime.now()
        order_details = {
            'item_id': item_id,
            'quantity': quantity,
            'order_date': order_date
        }
        self.purchase_orders.append(order_details)

    def update_supplier_record(self, item_id, supplier_name):
        if item_id in self.supplier_records:
            self.supplier_records[item_id]['supplier_name'] = supplier_name
        else:
            self.supplier_records[item_id] = {'supplier_name': supplier_name}

    def log_change(self, action, item_id, old_value=None, new_value=None):
        change_log = {
            'action': action,
            'item_id': item_id,
            'old_value': old_value,
            'new_value': new_value
        }
        self.alerts.append(change_log)

    def send_alert(self, alert_type, message):
        print(f"Alert: {alert_type} - {message}")
