        self.subscribers[topic].append(handler)

    def publish(self, event):
        self.events.append(event)
        for topic, handlers in self.subscribers.items():
            if topic in event.topic:
                for handler in handlers:
                    handler(event)

    async def handle_event(self, event):
        await asyncio.sleep(0)  # Simulate asynchronous processing
        print(f"Handling event: {event}")

async def main():
    bus = EventBus()

    @bus.subscribe("request", lambda event: print(f"Received request: {event}")
    @bus.subscribe("response", lambda event: print(f"Received response: {event}"))

    async def send_request(topic, data):
        event = {"topic": topic, "data": data}
        bus.publish(event)
        await bus.handle_event(event)

    async def receive_response(topic, data):
        event = {"topic": topic, "data": data}
        bus.publish(event)
        await bus.handle_event(event)

    await send_request("request", {"id": 1})
    await receive_response("response", {"id": 1})

if __name__ == "__main__":
    asyncio.run(main())
```

This Python implementation of an enterprise service bus supports synchronous calls, async messaging, event sourcing, saga pattern, and distributed transactions when only simple request-response is needed. It uses a dictionary to store subscribers and events, with each subscriber handling events based on their subscribed topics. The `handle_event` method simulates asynchronous processing by sleeping for 0 seconds. The `send_request` and `receive_response` functions are used to simulate sending and receiving requests and responses, respectively.

