    def __init__(self, initial_balance=10000):
        self.balance = initial_balance
        self.portfolio = {}
        self.order_book = {}
        self.trades = []
        self.risk_management = RiskManagement()
        self.execution_engine = ExecutionEngine()

    def place_order(self, symbol, quantity, side='buy'):
        if symbol not in self.order_book:
            self.order_book[symbol] = deque(maxlen=10)
        order = Order(symbol, quantity, side)
        self.order_book[symbol].append(order)
        self.risk_management.update_risk(symbol, quantity)

    def execute_orders(self):
        for symbol, orders in self.order_book.items():
            for order in orders:
                trade = self.execution_engine.execute_trade(symbol, order.quantity, order.side)
                if trade:
                    self.trades.append(trade)
